  ('g2-s1-calendar_patterns-easy-0005', 2, 1, 'calendar_patterns', 'easy', '{"start": 3, "n": 3}'::jsonb, 'Today is Thursday. What day of the week will it be 3 days from now?', '["Sunday", "Tuesday", "Saturday", "Monday"]'::jsonb, 'Sunday', '["counted one day too many", "counted one day too few", "counted two days too many"]'::jsonb, '3 mod 7 = 3, so count 3 days forward from Thursday to reach Sunday.', NULL, '', 15, NULL, 'template-mtap-g2-v1', true),
